export function firstPersonMovement(right,forward,yaw,speed,dt){const length=Math.max(1,Math.hypot(right,forward));return{x:(Math.cos(yaw)*right-Math.sin(yaw)*forward)/length*speed*dt,z:(-Math.sin(yaw)*right-Math.cos(yaw)*forward)/length*speed*dt}}
export function bindFirstPersonLook(canvas,isEnabled,onLook){const abort=new AbortController();let drag=null;const opts={signal:abort.signal};canvas.addEventListener('pointerdown',e=>{if(!isEnabled()||e.button>0)return;if(e.pointerType==='touch'&&e.clientX<canvas.getBoundingClientRect().left+canvas.clientWidth*.35)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);if(e.pointerType==='mouse'&&canvas.requestPointerLock)try{const pending=canvas.requestPointerLock();pending?.catch(()=>{})}catch{}},opts);document.addEventListener('mousemove',e=>{if(isEnabled()&&document.pointerLockElement===canvas)onLook(-e.movementX*.003,-e.movementY*.003)},opts);canvas.addEventListener('pointermove',e=>{if(!isEnabled()||!drag||drag.id!==e.pointerId||document.pointerLockElement===canvas)return;onLook(-(e.clientX-drag.x)*.005,-(e.clientY-drag.y)*.005);drag.x=e.clientX;drag.y=e.clientY},opts);const finish=()=>drag=null;canvas.addEventListener('pointerup',finish,opts);canvas.addEventListener('pointercancel',finish,opts);return()=>{abort.abort();if(document.pointerLockElement===canvas)document.exitPointerLock()}}
